    65→/// Leaderboard exporter.
    66→pub struct LeaderboardExporter {
    67→    db: Arc<Database>,
    68→}
    69→
    70→impl LeaderboardExporter {
    71→    /// Create a new exporter.
    72→    pub fn new(db: Arc<Database>) -> Self {
    73→        Self { db }
    74→    }
    75→
    76→    /// Export leaderboard to JSON.
    77→    pub fn export_json(&self, segment_id: Uuid) -> Result<String, ExportError> {
    78→        let export = self.build_export(segment_id)?;
    79→        serde_json::to_string_pretty(&export)
    80→            .map_err(|e| ExportError::SerializationFailed(e.to_string()))
    81→    }
    82→
    83→    /// Export leaderboard to CSV.
    84→    pub fn export_csv(&self, segment_id: Uuid) -> Result<String, ExportError> {
    85→        let export = self.build_export(segment_id)?;
    86→
    87→        let mut csv = String::new();
    88→        csv.push_str("rank,rider_name,elapsed_time_ms,avg_power_watts,recorded_at\n");
    89→
    90→        for effort in &export.efforts {
    91→            csv.push_str(&format!(
    92→                "{},{},{},{},{}\n",
    93→                effort.rank,
    94→                escape_csv(&effort.rider_name),
    95→                effort.elapsed_time_ms,
    96→                effort
    97→                    .avg_power_watts
    98→                    .map_or(String::new(), |p| p.to_string()),
    99→                effort.recorded_at.to_rfc3339(),
   100→            ));
   101→        }
   102→
   103→        Ok(csv)
   104→    }
   105→
   106→    /// Import efforts from JSON.
   107→    pub fn import_json(&self, json_content: &str) -> Result<ImportResult, ExportError> {
   108→        let export: LeaderboardExport = serde_json::from_str(json_content)
   109→            .map_err(|e| ExportError::ParseError(e.to_string()))?;
   110→
   111→        let conn = self.db.connection();
   112→
   113→        // Find or create segment
   114→        let segment_id = self.find_or_create_segment(&export.segment)?;
   115→
   116→        let mut imported_count = 0u32;
   117→        let mut duplicate_count = 0u32;
   118→        let mut name_conflicts = Vec::new();
   119→
   120→        // Group efforts by rider name
   121→        let mut efforts_by_name: std::collections::HashMap<String, Vec<&EffortExport>> =
   122→            std::collections::HashMap::new();
   123→        for effort in &export.efforts {
   124→            efforts_by_name
   125→                .entry(effort.rider_name.clone())
   126→                .or_default()
   127→                .push(effort);
   128→        }
   129→
   130→        // Process each rider
   131→        for (rider_name, efforts) in efforts_by_name {
   132→            // Check for existing rider with same name
   133→            let existing_rider_id = self.find_rider_by_name(&rider_name)?;
   134→
   135→            if let Some(rider_id) = existing_rider_id {
   136→                // Check if this is a name conflict (might be different person)
   137→                name_conflicts.push(NameConflict {
   138→                    imported_name: rider_name.clone(),
   139→                    existing_rider_id: Some(rider_id),
   140→                    effort_count: efforts.len() as u32,
   141→                });
   142→            }
   143→
   144→            // For now, import with a new rider ID (actual merge would require UI confirmation)
   145→            let import_rider_id = Uuid::new_v4();
   146→
   147→            for effort in efforts {
   148→                // Check for duplicate
   149→                if self.is_duplicate_effort(segment_id, &rider_name, effort.elapsed_time_ms)? {
   150→                    duplicate_count += 1;
   151→                    continue;
   152→                }
   153→
   154→                // Insert effort
   155→                let effort_id = Uuid::new_v4();
   156→                conn.execute(
   157→                    "INSERT INTO social_segment_efforts (id, segment_id, rider_id, elapsed_time_ms, avg_power_watts, recorded_at, imported, import_source_name)
   158→                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, 1, ?7)",
   159→                    rusqlite::params![
   160→                        effort_id.to_string(),
   161→                        segment_id.to_string(),
   162→                        import_rider_id.to_string(),
   163→                        effort.elapsed_time_ms,
   164→                        effort.avg_power_watts,
   165→                        effort.recorded_at.to_rfc3339(),
   166→                        rider_name,
   167→                    ],
   168→                )
   169→                .map_err(|e| ExportError::DatabaseError(e.to_string()))?;
   170→
   171→                imported_count += 1;
   172→            }
   173→        }
   174→
   175→        Ok(ImportResult {
   176→            imported_count,
   177→            duplicate_count,
   178→            name_conflicts,
   179→        })
   180→    }
   181→
   182→    fn build_export(&self, segment_id: Uuid) -> Result<LeaderboardExport, ExportError> {
   183→        let conn = self.db.connection();
   184→
   185→        // Get segment
   186→        let mut stmt = conn
   187→            .prepare(
   188→                "SELECT id, world_id, name, start_distance_m, end_distance_m, elevation_gain_m
   189→                 FROM social_segments WHERE id = ?1",
   190→            )
   191→            .map_err(|e| ExportError::DatabaseError(e.to_string()))?;
   192→
   193→        let segment_data = stmt
   194→            .query_row([segment_id.to_string()], |row| {
   195→                Ok((
   196→                    row.get::<_, String>(0)?,
   197→                    row.get::<_, String>(1)?,
   198→                    row.get::<_, String>(2)?,
   199→                    row.get::<_, f64>(3)?,
   200→                    row.get::<_, f64>(4)?,
   201→                    row.get::<_, f64>(5)?,
   202→                ))
   203→            })
   204→            .map_err(|_| ExportError::SegmentNotFound(segment_id))?;
   205→
   206→        let segment = SegmentExport {
   207→            id: segment_data.0,
   208→            name: segment_data.2,
   209→            world_id: segment_data.1,
   210→            distance_m: segment_data.4 - segment_data.3,
   211→            elevation_gain_m: segment_data.5,
   212→        };
   213→
   214→        // Get efforts
   215→        let mut stmt = conn
   216→            .prepare(
   217→                "SELECT e.rider_id, r.display_name, e.import_source_name, MIN(e.elapsed_time_ms) as best_time, e.avg_power_watts, e.recorded_at
   218→                 FROM social_segment_efforts e
   219→                 LEFT JOIN riders r ON e.rider_id = r.id
   220→                 WHERE e.segment_id = ?1
   221→                 GROUP BY e.rider_id
   222→                 ORDER BY best_time ASC",
   223→            )
   224→            .map_err(|e| ExportError::DatabaseError(e.to_string()))?;
   225→
   226→        let rows = stmt
   227→            .query_map([segment_id.to_string()], |row| {
   228→                Ok((
   229→                    row.get::<_, Option<String>>(1)?,
   230→                    row.get::<_, Option<String>>(2)?,
   231→                    row.get::<_, u32>(3)?,
   232→                    row.get::<_, Option<u16>>(4)?,
   233→                    row.get::<_, String>(5)?,
   234→                ))
   235→            })
   236→            .map_err(|e| ExportError::DatabaseError(e.to_string()))?;
   237→
   238→        let mut efforts = Vec::new();
   239→
   240→        for (rank, row) in rows.enumerate() {
   241→            let rank= (rank + 1) as u32;
   242→            let (display_name, import_name, elapsed_time_ms, avg_power, recorded_at_str) =
   243→                row.map_err(|e| ExportError::DatabaseError(e.to_string()))?;
