     2→//!
     3→//! T022-T030: FTP prediction implementation
     4→
     5→use std::sync::Arc;
     6→
     7→use chrono::NaiveDate;
     8→use serde::{Deserialize, Serialize};
     9→use uuid::Uuid;
    10→
    11→use super::client::MlClient;
    12→use super::types::{MlError, PredictionSource};
    13→use crate::metrics::analytics::{
    14→    FtpConfidence, FtpDetector, FtpMethod, PdcPoint as AnalyticsPdcPoint, PowerDurationCurve,
    15→};
    16→
    17→/// FTP prediction result.
    18→#[derive(Debug, Clone, Serialize, Deserialize)]
    19→pub struct FtpPredictionResult {
    20→    /// Predicted FTP in watts
    21→    pub predicted_ftp: u16,
    22→    /// Confidence level
    23→    pub confidence: FtpConfidence,
    24→    /// Method used for prediction
    25→    pub method_used: FtpMethod,
    26→    /// Efforts that support this prediction
    27→    pub supporting_efforts: Vec<SupportingEffort>,
    28→    /// Whether prediction differs significantly from current FTP
    29→    pub differs_from_current: bool,
    30→    /// Percentage difference from current FTP
    31→    pub difference_percent: f32,
    32→    /// Source of prediction (cloud, cache, local)
    33→    pub source: PredictionSource,
    34→}
    35→
    36→/// An effort that supports the FTP prediction.
    37→#[derive(Debug, Clone, Serialize, Deserialize)]
    38→pub struct SupportingEffort {
    39→    /// Ride ID
    40→    pub ride_id: Uuid,
    41→    /// Duration of the effort in seconds
    42→    pub duration_secs: u32,
    43→    /// Power in watts
    44→    pub power_watts: u16,
    45→    /// Date of the ride
    46→    pub ride_date: NaiveDate,
    47→}
    48→
    49→/// FTP predictor with cloud and local fallback.
    50→pub struct FtpPredictor {
    51→    client: Option<Arc<MlClient>>,
    52→    local_detector: FtpDetector,
    53→}
    54→
    55→impl FtpPredictor {
    56→    /// Create a new FTP predictor with cloud client.
    57→    pub fn new(client: Arc<MlClient>) -> Self {
    58→        Self {
    59→            client: Some(client),
    60→            local_detector: FtpDetector::new(),
    61→        }
    62→    }
    63→
    64→    /// Create a new FTP predictor for local-only predictions.
    65→    pub fn local_only() -> Self {
    66→        Self {
    67→            client: None,
    68→            local_detector: FtpDetector::new(),
    69→        }
    70→    }
    71→
    72→    /// Predict FTP from ride history.
    73→    ///
    74→    /// Attempts cloud prediction first, falls back to local detection.
    75→    pub async fn predict(
    76→        &self,
    77→        _user_id: Uuid,
    78→        rides: &[RideSummary],
    79→        current_ftp: u16,
    80→    ) -> Result<FtpPredictionResult, MlError> {
    81→        // Check minimum data requirements
    82→        if rides.len() < 5 {
    83→            return Err(MlError::InsufficientData {
    84→                message: format!("Only {} rides available, need at least 5", rides.len()),
    85→                guidance: "Complete more varied-intensity rides to enable FTP prediction.".into(),
    86→            });
    87→        }
    88→
    89→        // Try cloud prediction if available
    90→        if let Some(_client) = &self.client {
    91→            // TODO: Implement cloud API call when backend is ready
    92→            // For now, fall through to local prediction
    93→        }
    94→
    95→        // Fall back to local prediction
    96→        self.predict_local(rides, current_ftp)
    97→    }
    98→
    99→    /// Predict FTP using local algorithm only.
   100→    pub fn predict_local(
   101→        &self,
   102→        rides: &[RideSummary],
   103→        current_ftp: u16,
   104→    ) -> Result<FtpPredictionResult, MlError> {
   105→        // Collect PDC points from rides
   106→        let pdc_points: Vec<AnalyticsPdcPoint> = rides
   107→            .iter()
   108→            .flat_map(|r| {
   109→                r.pdc_points.iter().map(|p| AnalyticsPdcPoint {
   110→                    duration_secs: p.duration_secs,
   111→                    power_watts: p.power_watts,
   112→                })
   113→            })
   114→            .collect();
   115→
   116→        if pdc_points.is_empty() {
   117→            return Err(MlError::InsufficientData {
   118→                message: "No power duration curve data available".into(),
   119→                guidance: "Record rides with consistent power efforts to build your power curve."
   120→                    .into(),
   121→            });
   122→        }
   123→
   124→        // Build PDC and use existing FTP detector
   125→        let pdc = PowerDurationCurve::from_points(pdc_points);
   126→        let estimate =
   127→            self.local_detector
   128→                .detect(&pdc)
   129→                .ok_or_else(|| MlError::InsufficientData {
   130→                    message: "Could not estimate FTP from available data".into(),
   131→                    guidance: "Record longer efforts (20+ minutes) at high intensity.".into(),
   132→                })?;
   133→
   134→        let supporting_efforts: Vec<SupportingEffort> = rides
   135→            .iter()
   136→            .filter_map(|r| {
   137→                r.pdc_points
   138→                    .iter()
   139→                    .find(|p| p.duration_secs >= 1200)
   140→                    .map(|p| SupportingEffort {
   141→                        ride_id: r.ride_id,
   142→                        duration_secs: p.duration_secs,
   143→                        power_watts: p.power_watts,
   144→                        ride_date: r.date,
   145→                    })
   146→            })
   147→            .take(5)
   148→            .collect();
   149→
   150→        let difference_percent = if current_ftp > 0 {
   151→            ((estimate.ftp_watts as f32 - current_ftp as f32) / current_ftp as f32) * 100.0
   152→        } else {
   153→            0.0
   154→        };
   155→
   156→        Ok(FtpPredictionResult {
   157→            predicted_ftp: estimate.ftp_watts,
   158→            confidence: estimate.confidence,
   159→            method_used: estimate.method,
   160→            supporting_efforts,
   161→            differs_from_current: difference_percent.abs() > 3.0,
   162→            difference_percent,
   163→            source: PredictionSource::LocalFallback,
   164→        })
   165→    }
   166→
   167→    /// Check if prediction warrants user notification.
   168→    pub fn should_notify(&self, prediction: &FtpPredictionResult, current_ftp: u16) -> bool {
   169→        prediction.differs_from_current
   170→            && prediction.difference_percent.abs() > 3.0
   171→            && prediction.confidence != FtpConfidence::Low
   172→            && current_ftp > 0
   173→    }
   174→}
