    91→    /// Update avatar position based on speed and route
    92→    ///
    93→    /// # Arguments
    94→    /// * `speed_mps` - Current speed in meters per second
    95→    /// * `route` - The route being followed
    96→    /// * `delta_time` - Time since last update in seconds
    97→    pub fn update(&mut self, speed_mps: f32, route: &Route, delta_time: f32) {
    98→        // Update distance along route
    99→        self.distance_on_route += speed_mps * delta_time;
   100→
   101→        // Wrap around if past the end of a loop route
   102→        if self.distance_on_route > route.total_distance {
   103→            self.distance_on_route %= route.total_distance;
   104→        }
   105→
   106→        // Get new position and heading from route
   107→        let (position, heading) = route.get_position(self.distance_on_route);
   108→        self.position = position;
   109→        self.rotation = heading;
   110→
   111→        // Update animation based on speed
   112→        if speed_mps < 0.5 {
   113→            self.animation_state = AnimationState::Idle;
   114→        } else {
   115→            // Estimate cadence from speed (simplified)
   116→            let estimated_cadence = (speed_mps * 12.0).clamp(40.0, 120.0);
   117→            self.animation_state = AnimationState::Pedaling {
   118→                cadence: estimated_cadence,
   119→            };
   120→        }
   121→    }
   122→
   123→    /// Set pedaling cadence explicitly (from sensor data)
   124→    pub fn set_cadence(&mut self, cadence: u8) {
   125→        if cadence > 0 {
   126→            self.animation_state = AnimationState::Pedaling {
   127→                cadence: cadence as f32,
   128→            };
   129→        } else {
   130→            self.animation_state = AnimationState::Coasting;
   131→        }
   132→    }
   133→
   134→    /// Get the direction the avatar is facing
   135→    pub fn direction(&self) -> Vec3 {
   136→        Vec3::new(self.rotation.cos(), 0.0, self.rotation.sin())
   137→    }
   138→
   139→    /// Get current distance traveled on route
   140→    pub fn distance_traveled(&self) -> f32 {
   141→        self.distance_on_route
   142→    }
   143→
   144→    /// Reset position to start of route
   145→    pub fn reset(&mut self) {
   146→        self.distance_on_route = 0.0;
   147→        self.position = Vec3::ZERO;
   148→        self.rotation = 0.0;
   149→        self.animation_state = AnimationState::Idle;
   150→    }
   151→}
