   631→    /// Import a profile export to the database.
   632→    ///
   633→    /// Imports profile data, FTP history, and avatar configuration using
   634→    /// the specified conflict resolution strategy.
   635→    ///
   636→    /// # Strategies
   637→    /// - `Replace`: Completely overwrite existing profile data
   638→    /// - `Merge`: Combine FTP history, keeping both existing and imported entries
   639→    /// - `Skip`: Do not import anything, return immediately
   640→    ///
   641→    /// # Arguments
   642→    /// * `export` - The parsed profile export to import
   643→    /// * `resolution` - Strategy for handling conflicts with existing data
   644→    ///
   645→    /// # Returns
   646→    /// A `ProfileImportResult` with details about what was imported/skipped.
   647→    ///
   648→    /// # Example
   649→    /// ```ignore
   650→    /// let exporter = ProfileExporter::new(db);
   651→    /// let export = exporter.parse_import(json_content)?;
   652→    /// let result = exporter.import_profile(&export, ConflictResolution::Merge)?;
   653→    /// if result.success {
   654→    ///     println!("Imported {} FTP entries", result.ftp_entries_imported);
   655→    /// }
   656→    /// ```
   657→    pub fn import_profile(
   658→        &self,
   659→        export: &ProfileExport,
   660→        resolution: ConflictResolution,
   661→    ) -> Result<ProfileImportResult, ProfileExportError> {
   662→        // Skip strategy: return immediately without changes
   663→        if resolution == ConflictResolution::Skip {
   664→            return Ok(ProfileImportResult {
   665→                success: true,
   666→                ftp_entries_imported: 0,
   667→                ftp_entries_skipped: 0,
   668→                profile_updated: false,
   669→                avatar_updated: false,
   670→                conflicts: Vec::new(),
   671→            });
   672→        }
   673→
   674→        let conn = self.db.connection();
   675→
   676→        // Check if profile exists
   677→        let existing_profile = self.query_existing_profile(&conn, export.rider_id)?;
   678→
   679→        let profile_updated;
   680→        let avatar_updated;
   681→
   682→        match resolution {
   683→            ConflictResolution::Replace => {
   684→                // Replace: delete existing data and insert fresh
   685→                profile_updated = self.import_profile_data_replace(&conn, export)?;
   686→                avatar_updated = self.import_avatar_replace(&conn, export)?;
   687→            }
   688→            ConflictResolution::Merge => {
   689→                // Merge: update profile, keep existing data where appropriate
   690→                profile_updated = if existing_profile.is_some() {
   691→                    self.import_profile_data_update(&conn, export)?
   692→                } else {
   693→                    self.import_profile_data_insert(&conn, export)?
   694→                };
   695→                avatar_updated = self.import_avatar_merge(&conn, export)?;
   696→            }
   697→            ConflictResolution::Skip => {
   698→                // Already handled above
   699→                unreachable!()
   700→            }
   701→        }
   702→
   703→        // Import FTP history based on strategy
   704→        let (ftp_entries_imported, ftp_entries_skipped) = match resolution {
   705→            ConflictResolution::Replace => {
   706→                // Delete all existing FTP entries and import fresh
   707→                self.delete_ftp_history(&conn, export.rider_id)?;
   708→                let imported = self.import_ftp_history_all(&conn, export)?;
   709→                (imported, 0)
   710→            }
   711→            ConflictResolution::Merge => {
   712→                // Merge FTP history, skipping duplicates
   713→                self.import_ftp_history_merge(&conn, export)?
   714→            }
   715→            ConflictResolution::Skip => (0, 0),
   716→        };
   717→
   718→        Ok(ProfileImportResult::success(
   719→            ftp_entries_imported,
   720→            ftp_entries_skipped,
   721→            profile_updated,
   722→            avatar_updated,
   723→        ))
