   643→    /// T019: Render details about detected conflicts.
   644→    fn render_conflict_details(
   645→        &self,
   646→        ui: &mut Ui,
   647→        conflicts: &[ProfileConflict],
   648→        export: &ProfileExport,
   649→    ) {
   650→        if conflicts.is_empty() {
   651→            ui.label(
   652→                RichText::new("No conflicts detected. Profile can be imported directly.")
   653→                    .color(Color32::from_rgb(76, 175, 80)),
   654→            );
   655→            return;
   656→        }
   657→
   658→        for conflict in conflicts {
   659→            match conflict {
   660→                ProfileConflict::ExistingProfile {
   661→                    existing_name,
   662→                    rider_id: _,
   663→                } => {
   664→                    ui.horizontal(|ui| {
   665→                        ui.label("•");
   666→                        ui.label(format!(
   667→                            "Profile exists: \"{}\" → \"{}\"",
   668→                            existing_name, export.profile.display_name
   669→                        ));
   670→                    });
   671→                }
   672→                ProfileConflict::DisplayNameMismatch {
   673→                    imported_name,
   674→                    existing_name,
   675→                } => {
   676→                    ui.horizontal(|ui| {
   677→                        ui.label("•");
   678→                        ui.label(format!(
   679→                            "Name change: \"{}\" → \"{}\"",
   680→                            existing_name, imported_name
   681→                        ));
   682→                    });
   683→                }
   684→                ProfileConflict::FtpMismatch {
   685→                    imported_ftp,
   686→                    existing_ftp,
   687→                } => {
   688→                    ui.horizontal(|ui| {
   689→                        ui.label("•");
   690→                        let existing = existing_ftp
   691→                            .map(|f| format!("{}W", f))
   692→                            .unwrap_or_else(|| "None".to_string());
   693→                        let imported = imported_ftp
   694→                            .map(|f| format!("{}W", f))
   695→                            .unwrap_or_else(|| "None".to_string());
   696→                        ui.label(format!("FTP change: {} → {}", existing, imported));
   697→                    });
   698→                }
   699→                ProfileConflict::AvatarMismatch {
   700→                    import_has_avatar,
   701→                    existing_has_avatar,
   702→                } => {
   703→                    ui.horizontal(|ui| {
   704→                        ui.label("•");
   705→                        let msg = match (existing_has_avatar, import_has_avatar) {
   706→                            (true, true) => "Avatar will be replaced",
   707→                            (true, false) => "Avatar will be removed",
   708→                            (false, true) => "Avatar will be added",
   709→                            (false, false) => "No avatar changes",
   710→                        };
   711→                        ui.label(msg);
   712→                    });
   713→                }
   714→            }
